{
  "schemaVersion": "0.2",
  "slug": "table",
  "name": "Table",
  "status": "experimental",
  "purpose": "Presents tabular data with semantic rows and columns.",
  "scenarios": [
    "Display a list of users with sortable columns",
    "Show order line items with prices",
    "Present a read-only data summary"
  ],
  "props": {
    "columns": {
      "type": "string",
      "required": true,
      "description": "Column definitions with key, header, and optional render function."
    },
    "rows": {
      "type": "string",
      "required": true,
      "description": "Array of row data objects."
    },
    "caption": {
      "type": "string",
      "required": false,
      "description": "Accessible caption for the table."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Table is rendered with the provided rows."
    }
  ],
  "composition": {
    "allowedParents": [
      "dialog",
      "app-shell",
      "page"
    ],
    "allowedChildren": [
      "text",
      "button"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use a table solely for layout; use Stack or AppShell.",
    "Do not remove header cells from data tables."
  ],
  "a11y": {
    "role": "table",
    "keyboard": [
      "Tab moves through focusable cells",
      "Arrow keys move between cells if interactive"
    ],
    "focus": "Cells are not individually focusable unless they contain interactive elements.",
    "labeling": "Caption or surrounding context labels the table; headers use scope=col.",
    "wcag": [
      "1.3.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Full table on desktop and tablet; compact scrolls horizontally. Card-list morph is contract-described only (demo pending), not implemented. Compact switch is container-driven via @container on the wrapper.",
    "breakpoints": {
      "compact": "Horizontal scroll within the component container if content overflows; reduced cell padding below the 48rem container threshold.",
      "medium": "Full width with comfortable padding.",
      "large": "Full width with comfortable padding."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Text alignment and row order follow the document direction.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "table",
    "states": [
      "default"
    ],
    "intents": [
      "inspect-tabular-data"
    ]
  }
}

{
  "table": {
    "caption": "データテーブル",
    "name": "名前",
    "status": "ステータス"
  }
}

/*
 * Phase 5 container-query whitelist member: the root is the query container,
 * so compact padding follows the table's own inline size, not the viewport.
 */
.cu-table {
  inline-size: 100%;
  overflow: auto;
  container-type: inline-size;
}

.cu-table__table {
  inline-size: 100%;
  border-collapse: collapse;
  color: var(--cu-color-fg-default);
}

.cu-table__caption {
  caption-side: top;
  text-align: start;
  font-weight: 700;
  margin-block-end: var(--cu-space-2);
}

.cu-table__header,
.cu-table__cell {
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border-block-end: 1px solid var(--cu-color-border-default);
  text-align: start;
}

.cu-table__header {
  font-weight: 700;
  color: var(--cu-color-fg-default);
  background: color-mix(in srgb, var(--cu-color-background-inverse) 4%, var(--cu-color-background-default));
}

/* Hover is gated so touch input never sticks in a hover style. */
@media (hover: hover) {
  .cu-table__row:hover {
    background: color-mix(in srgb, var(--cu-color-palette-brand) 4%, transparent);
  }
}

/* 47.99rem == breakpoint.tablet (48rem) lower-bound companion, see breakpoint.json. */
@container (max-width: 47.99rem) {
  .cu-table__table {
    min-inline-size: 100%;
  }

  .cu-table__header,
  .cu-table__cell {
    padding-inline: var(--cu-space-2);
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export interface TableColumn<T = unknown> {
  key: string
  header: ReactNode
  render?: (row: T) => ReactNode
}

export interface TableProps<T = unknown> {
  columns: TableColumn<T>[]
  rows: T[]
  getRowId?: (row: T, index: number) => string
  caption?: string
  className?: string
}

export function Table<T>({ columns, rows, getRowId, caption, className }: TableProps<T>) {
  const classes = ['cu-table', className].filter(Boolean).join(' ')

  return (
    <div className={classes} data-ai-role="table" data-ai-intent="inspect-tabular-data" data-ai-state={rows.length === 0 ? 'empty' : 'default'}>
      <table className="cu-table__table">
        {caption ? <caption className="cu-table__caption">{caption}</caption> : null}
        <thead className="cu-table__head">
          <tr>
            {columns.map((column) => (
              <th key={column.key} className="cu-table__header" scope="col">
                {column.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="cu-table__body">
          {rows.map((row, index) => (
            <tr key={getRowId ? getRowId(row, index) : index} className="cu-table__row">
              {columns.map((column) => (
                <td key={column.key} className="cu-table__cell">
                  {column.render ? column.render(row) : String((row as Record<string, ReactNode>)[column.key])}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}
